const META = [
  { Icon: TargetIcon, badgeBorder: "rgba(201,168,76,0.25)", badgeBg: "rgba(201,168,76,0.12)", rowBg: "rgba(201,168,76,0.07)" },
  { Icon: AgentIcon, badgeBorder: "rgba(32,231,242,0.18)", badgeBg: "rgba(32,231,242,0.12)", rowBg: "rgba(32,231,242,0.07)" },
  { Icon: WorkflowIcon, badgeBorder: "rgba(139,92,246,0.22)", badgeBg: "rgba(139,92,246,0.10)", rowBg: "rgba(139,92,246,0.07)" },
  { Icon: ShieldIcon, badgeBorder: "rgba(34,197,94,0.22)", badgeBg: "rgba(34,197,94,0.10)", rowBg: "rgba(34,197,94,0.07)" },
  { Icon: IntegrationIcon, badgeBorder: "rgba(245,158,11,0.22)", badgeBg: "rgba(245,158,11,0.10)", rowBg: "rgba(245,158,11,0.07)" },
  { Icon: EvidenceIcon, badgeBorder: "rgba(239,68,68,0.18)", badgeBg: "rgba(239,68,68,0.08)", rowBg: "rgba(239,68,68,0.07)" },
  { Icon: GridIcon, badgeBorder: "rgba(32,231,242,0.18)", badgeBg: "rgba(32,231,242,0.12)", rowBg: "rgba(32,231,242,0.07)" },
];

export default function AgenticArchitectureLayers() {
  const [active, setActive] = useState(0);
  const layer = LAYERS[active];

  return (
    <section className="bg-[#080812] py-24">
      <div className="max-w-7xl mx-auto px-6 lg:px-12">
        <div className="mb-12">
          <div className="inline-flex items-center gap-2 mb-4">
            <span className="w-4 h-px bg-[#20E7F2]" />
            <span className="text-[10px] font-bold uppercase tracking-[0.2em] text-[#20E7F2]">Architecture Layers</span>
          </div>
          <h2 className="text-[clamp(1.8rem,3.5vw,2.6rem)] font-black leading-tight text-white max-w-2xl mb-4">
            The governed agentic operating model.
          </h2>
          <p className="text-white/45 text-[14.5px] leading-relaxed max-w-xl">
            Seven interconnected layers that turn business goals into governed, evidenced, measurable enterprise execution. Select any layer to explore.
          </p>
        </div>

        <div className="grid lg:grid-cols-[1.3fr_1fr] gap-6 items-start">
          {/* Layer list */}
          <div className="flex flex-col gap-1.5 rounded-2xl overflow-hidden">
            {LAYERS.map((l, i) => {
              const isActive = i === active;
              const m = META[i];
              return (
                <button
                  key={l.id}
                  onClick={() => setActive(i)}
                  className="w-full flex items-center gap-4 px-5 py-4 text-left rounded-lg transition-all"
                  style={{
                    background: m.rowBg,
                    border: `1px solid ${isActive ? m.badgeBorder : "rgba(0,0,0,0.00)"}`,
                    boxShadow: isActive
                      ? "0 0 0 1px rgba(32,231,242,0.18), 0 8px 32px 0 rgba(32,231,242,0.08)"
                      : "none",
                  }}
                >
                  <span className="text-[11px] font-mono text-white/25 w-5 shrink-0">{l.number}</span>
                  <div
                    className="w-9 h-9 rounded-[9px] flex items-center justify-center shrink-0"
                    style={{ background: m.badgeBg, border: `1px solid ${m.badgeBorder}`, color: l.color }}
                  >
                    <m.Icon className="w-4 h-4" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-[14px] font-bold text-white leading-snug">{l.title}</p>
                    <p className="text-[12px] text-white/40 leading-snug mt-0.5 truncate">{l.subtitle}</p>
                  </div>
                  <ChevronRight className={`shrink-0 transition-colors ${isActive ? "text-white/70" : "text-white/20"}`} />
                </button>
              );
            })}
          </div>

          {/* Detail panel */}
          <div className="rounded-2xl border border-white/10 bg-[#0d1420] overflow-hidden sticky top-24 w-[380px] max-w-full">
            <div className="relative w-[378px] max-w-full h-[180px] mx-auto mt-0.5">
              <Image src={layer.image} alt={layer.title} fill className="object-cover" sizes="378px" />
              <div className="absolute inset-0 bg-gradient-to-t from-[#0d1420] via-[#0d1420]/20 to-transparent" />
              <span
                className="absolute top-4 left-4 text-[10px] font-bold uppercase tracking-[0.15em] px-2.5 py-1 rounded-full"
                style={{ color: layer.color, background: "rgba(0,0,0,0.5)", border: `1px solid ${layer.colorBorder}` }}
              >
                {layer.tag}
              </span>
            </div>
            <div className="p-6">
              <p className="text-[11px] font-mono uppercase tracking-wider text-white/35 mb-2">
                Layer {layer.number} · {layer.tag}
              </p>
              <h3 className="text-white font-black text-xl mb-3">{layer.title}</h3>
              <p className="text-white/50 text-[13.5px] leading-relaxed mb-6">{layer.description}</p>
              <Link
                href="/request-demo"
                className="inline-flex items-center gap-2"
                style={{
                  color: "#20E7F2",
                  fontFamily: "var(--font-jakarta), sans-serif",
                  fontSize: "13px",
                  fontWeight: 500,
                  lineHeight: "normal",
                }}
              >
                Request a Demo
                <ArrowRight />
              </Link>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
